package com.gomgomapps.math.core;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public class ButtonPlateStoriesTest {
 @Test public void allPublicContextsExhaustBeforeOldestWithoutHiddenKeys(){Generator g=new Generator(new Random(125));var limits=GlobalCurriculum.limits("england-primary-2021-v1",ButtonPlateStories.ID,2);List<String> recent=new ArrayList<>();Map<Integer,Integer> modes=new HashMap<>();for(int i=0;i<117;i++){Question q=g.next(ButtonPlateStories.ID,recent,true,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());int[] v=ButtonPlateStories.read(q);assertNotNull(v);modes.merge(v[0],1,Integer::sum);int expected=v[0]==0?(int)(q.diagram.values[0]*q.diagram.values[1]):(int)(q.diagram.values[0]/q.diagram.values[1]);q.answers=new String[]{"poison"};assertTrue(new Checker().check(q,List.of(),List.of(""+expected)).correct());assertFalse(new Checker().check(q,List.of(),List.of(""+(expected+1))).correct());assertTrue(q.choices.isEmpty());HelpPlan p=HelpPlan.forQuestion(q);assertFalse(p.canTransfer());assertEquals(4,p.size());assertTrue(p.step(0).accepts(new String[]{"total","share","group"}[v[0]]));assertTrue(p.step(1).accepts(""+v[1]));assertTrue(p.step(2).accepts(""+v[2]));assertTrue(p.step(3).accepts(""+expected));for(int s=0;s<p.size();s++)assertFalse(p.step(s).before.matches(".*\\d.*"));}assertEquals(Map.of(0,39,1,39,2,39),modes);assertEquals(recent.get(0),g.next(ButtonPlateStories.ID,recent,false,limits).signature());}
 @Test public void zeroMaximumAndMalformedPublicStories(){for(int mode=0;mode<3;mode++)for(int n:List.of(0,12)){Question q=ButtonPlateStories.make(mode,mode==0?10:10*n,mode==0?n:10);assertNotNull(ButtonPlateStories.read(q));}Question q=ButtonPlateStories.make(1,20,5);q.diagram.values[0]=21;assertNull(ButtonPlateStories.read(q));q=ButtonPlateStories.make(2,20,5);q.prompt=q.prompt.replace("20","21");assertNull(ButtonPlateStories.read(q));q=ButtonPlateStories.make(0,5,4);q.diagram.values[0]=Double.NaN;assertNull(ButtonPlateStories.read(q));Learning.Profile p=new Learning.Profile();GlobalCurriculum.chooseCountry(p,"GB");GlobalCurriculum.choosePack(p,"england-primary-2021-v1");assertTrue(GlobalCurriculum.pack(p).inGrade(ButtonPlateStories.ID,2));assertFalse(GlobalCurriculum.pack(p).inGrade(ButtonPlateStories.ID,1));}
}
